using System.Globalization;
using GroupLab.Cli.Bench;

namespace GroupLab.Cli;

/// <summary>
/// <c>grouplab bench</c>, NOTES-FROM-PLANNING.md entry 117 section 4: GroupLab measuring itself, with no input from anybody. Every case runs
/// against material committed in this repository or generated by GroupLab from its own sheet, so it runs on a bare checkout, on CI and on a
/// machine that has never analysed a target.
/// <para>
/// It optimises nothing and changes nothing. It prints a table, and with <c>-o</c> writes the same table as Markdown, which is how the
/// committed record in <c>docs/PERFORMANCE.md</c> is made.
/// </para>
/// </summary>
public static class BenchVerb
{
    public const string Usage = "grouplab bench [--runs <n>] [--area <name>]... [--root <directory>] [-o <record.md>] [--record <document.md>] [--commit <sha>]";

    public static int Run(string[] args, TextWriter output, TextWriter error)
    {
        ArgumentNullException.ThrowIfNull(args);
        ArgumentNullException.ThrowIfNull(output);
        ArgumentNullException.ThrowIfNull(error);
        int runs = BenchRunner.DefaultRuns;
        string? into = null, record = null, root = null, commit = null;
        var areas = new List<string>();
        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "--runs" when i + 1 < args.Length && int.TryParse(args[i + 1], NumberStyles.None, CultureInfo.InvariantCulture, out int n) && n > 0:
                    runs = n;
                    i++;
                    break;
                case "--area" when i + 1 < args.Length:
                    areas.Add(args[++i]);
                    break;
                case "--root" when i + 1 < args.Length:
                    root = args[++i];
                    break;
                case "--commit" when i + 1 < args.Length:
                    commit = args[++i];
                    break;
                case "-o" when i + 1 < args.Length:
                    into = args[++i];
                    break;
                // The committed record is one document with prose around it, so the table goes into it in place rather than over it.
                case "--record" when i + 1 < args.Length:
                    record = args[++i];
                    break;
                default:
                    error.WriteLine($"bench: unknown option {args[i]}");
                    error.WriteLine(Usage);
                    return 2;
            }
        }

        foreach (string area in areas.Where(a => !BenchSuite.Areas.Contains(a, StringComparer.Ordinal)))
        {
            error.WriteLine($"bench: there is no area {area}. The areas are {string.Join(", ", BenchSuite.Areas)}.");
            return 2;
        }

        using var material = BenchMaterial.Prepare(root);
        var cases = BenchSuite.All(material).Where(c => areas.Count == 0 || areas.Contains(c.Area, StringComparer.Ordinal)).ToList();
        var machine = BenchMachine.Here(runs, commit ?? Commit(material.Root));
        output.WriteLine($"GroupLab bench: {cases.Count} cases, {runs} timed runs of each, on {machine.Name}, {machine.Configuration}, commit {machine.Commit}.");
        output.WriteLine("Nothing here is optimised and nothing is changed. Anything wasteful is written down, not fixed.");
        output.WriteLine();

        var measured = BenchRunner.Run(cases, runs, m => output.WriteLine(BenchReport.Line(m)));
        output.WriteLine();
        int unmeasured = measured.Count(m => m.Failure is not null);
        output.WriteLine($"{measured.Count} figures, {unmeasured} not measured.");

        if (into is not null || record is not null)
        {
            string markdown = BenchReport.Markdown(measured, BenchSuite.Exclusions, machine);
            if (into is not null)
            {
                Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(into))!);
                File.WriteAllText(into, markdown);
                output.WriteLine($"Wrote {into}.");
            }

            if (record is not null)
            {
                BenchReport.Replace(record, "## The record", markdown);
                output.WriteLine($"Put the record into {record}.");
            }
        }

        return 0;
    }

    /// <summary>The commit the build came from, where this is a working copy and git is here. A record that does not name one says so.</summary>
    private static string? Commit(string root)
    {
        try
        {
            using var git = System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("git", "rev-parse --short HEAD")
            {
                WorkingDirectory = root,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            });
            if (git is null)
            {
                return null;
            }

            string sha = git.StandardOutput.ReadToEnd().Trim();
            git.WaitForExit(5000);
            return git.ExitCode == 0 && sha.Length > 0 ? sha : null;
        }
        catch (Exception ex) when (ex is System.ComponentModel.Win32Exception or InvalidOperationException or IOException)
        {
            return null;
        }
    }
}
